// Command gensdk turns api/redx-api.json, the source of truth of the RedX HTTP API, into api/openapi.json and the
// operation tables of every SDK (Go, JavaScript/TypeScript, Python, Swift, C#, C). Run it from the repository
// root after changing the spec:
//
//	go run ./scripts/gensdk          write the generated files
//	go run ./scripts/gensdk -check   fail if a generated file is out of date (CI)
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"unicode"
)

type Danger struct {
	Name    string `json:"name"`
	Level   int    `json:"level"`
	Meaning string `json:"meaning"`
}

type Op struct {
	ID        string            `json:"id"`
	Group     string            `json:"group"`
	Method    string            `json:"method"`
	Path      string            `json:"path"`
	Shorthand string            `json:"shorthand,omitempty"`
	Auth      string            `json:"auth"`
	Danger    string            `json:"danger"`
	Summary   string            `json:"summary"`
	Response  string            `json:"response"`
	Request   string            `json:"request,omitempty"` // binary | text (otherwise JSON when Body is set)
	Body      map[string]string `json:"body,omitempty"`
	Query     map[string]string `json:"query,omitempty"`
	Notes     string            `json:"notes,omitempty"`
	// HostConfirm names the parameter a confirmed call repeats as ?confirm= (deleteDatabase: the db name).
	HostConfirm string `json:"hostConfirm,omitempty"`
}

type Spec struct {
	Name          string            `json:"name"`
	Version       string            `json:"version"`
	Auth          map[string]string `json:"auth"`
	Danger        []Danger          `json:"danger"`
	RALevels      map[string]string `json:"rottenAppleLevels"`
	ParamEncoding struct {
		Segments []string `json:"segments"`
	} `json:"paramEncoding"`
	Operations []Op `json:"operations"`
}

var reParam = regexp.MustCompile(`\{([a-z][a-z0-9_]*)\}`)

func (o Op) params() []string {
	var out []string
	for _, m := range reParam.FindAllStringSubmatch(o.Path, -1) {
		out = append(out, m[1])
	}
	return out
}
func (o Op) pathParams() []string { // without db
	var out []string
	for _, p := range o.params() {
		if p != "db" {
			out = append(out, p)
		}
	}
	return out
}
func (o Op) hasDB() bool   { return strings.Contains(o.Path, "{db}") }
func (o Op) hasBody() bool { return o.Body != nil || o.Request != "" }

func pascal(s string) string { r := []rune(s); r[0] = unicode.ToUpper(r[0]); return string(r) }
func snake(s string) string {
	var b strings.Builder
	for i, r := range s {
		if unicode.IsUpper(r) {
			if i > 0 {
				b.WriteByte('_')
			}
			b.WriteRune(unicode.ToLower(r))
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func level(s *Spec, name string) int {
	for _, d := range s.Danger {
		if d.Name == name {
			return d.Level
		}
	}
	panic("unknown danger " + name)
}

const header = "Code generated by scripts/gensdk from api/redx-api.json. DO NOT EDIT."

func main() {
	check := flag.Bool("check", false, "fail if generated files are out of date")
	flag.Parse()
	b, err := os.ReadFile("api/redx-api.json")
	if err != nil {
		fmt.Fprintln(os.Stderr, "run from the repository root:", err)
		os.Exit(1)
	}
	var s Spec
	if err := json.Unmarshal(b, &s); err != nil {
		fmt.Fprintln(os.Stderr, "api/redx-api.json:", err)
		os.Exit(1)
	}
	if err := validate(&s); err != nil {
		fmt.Fprintln(os.Stderr, "api/redx-api.json:", err)
		os.Exit(1)
	}
	files := map[string]string{
		"api/openapi.json":                        openapi(&s),
		"sdk/go/redx/operations_gen.go":           goOps(&s),
		"sdk/js/operations.js":                    jsOps(&s),
		"sdk/js/operations.d.ts":                  tsOps(&s),
		"sdk/python/redx/operations.py":           pyOps(&s),
		"sdk/swift/Sources/RedX/Operations.swift": swiftOps(&s),
		"sdk/csharp/RedX/Operations.g.cs":         csOps(&s),
		"sdk/go/cabi/include/redx_ops.h":          cOps(&s),
	}
	names := make([]string, 0, len(files))
	for n := range files {
		names = append(names, n)
	}
	sort.Strings(names)
	stale := 0
	for _, n := range names {
		old, _ := os.ReadFile(n)
		if bytes.Equal(old, []byte(files[n])) {
			continue
		}
		if *check {
			fmt.Fprintln(os.Stderr, "out of date:", n)
			stale++
			continue
		}
		os.MkdirAll(filepath.Dir(n), 0o755)
		if err := os.WriteFile(n, []byte(files[n]), 0o644); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		fmt.Println("wrote", n)
	}
	if stale > 0 {
		fmt.Fprintln(os.Stderr, "run: go run ./scripts/gensdk")
		os.Exit(1)
	}
}

func validate(s *Spec) error {
	seen := map[string]bool{}
	for _, o := range s.Operations {
		if seen[o.ID] {
			return fmt.Errorf("duplicate id %s", o.ID)
		}
		seen[o.ID] = true
		if _, ok := s.Auth[o.Auth]; !ok {
			return fmt.Errorf("%s: unknown auth %s", o.ID, o.Auth)
		}
		level(s, o.Danger)
		switch o.Response {
		case "json", "text", "binary", "websocket":
		default:
			return fmt.Errorf("%s: unknown response %s", o.ID, o.Response)
		}
		if o.Auth == "host-admin" || o.Auth == "admin" {
			// every admin call is at least "admin" or reads only
			if o.Method != "GET" && level(s, o.Danger) < 1 {
				return fmt.Errorf("%s: an admin call that changes something cannot be safe", o.ID)
			}
		}
	}
	return nil
}

func segs(s *Spec) map[string]bool {
	m := map[string]bool{}
	for _, x := range s.ParamEncoding.Segments {
		m[x] = true
	}
	return m
}

// ---------------------------------------------------------------- OpenAPI

func openapi(s *Spec) string {
	paths := map[string]map[string]interface{}{}
	for _, o := range s.Operations {
		if o.ID == "getPathBox" { // same route as getPath, with Accept: text/x-redx-box
			continue
		}
		p := map[string]interface{}{
			"operationId":         o.ID,
			"summary":             o.Summary,
			"tags":                []string{o.Group},
			"x-redx-auth":         o.Auth,
			"x-redx-danger":       o.Danger,
			"x-redx-danger-level": level(s, o.Danger),
			"x-rottenapple-level": s.RALevels[o.Danger],
		}
		if o.Notes != "" {
			p["description"] = o.Notes
		}
		if o.Shorthand != "" {
			p["x-redx-shorthand"] = o.Shorthand
		}
		if o.Auth == "none" {
			p["security"] = []interface{}{}
		}
		var params []interface{}
		for _, n := range o.params() {
			params = append(params, map[string]interface{}{"name": n, "in": "path", "required": true, "schema": map[string]string{"type": "string"}})
		}
		qk := keys(o.Query)
		for _, k := range qk {
			params = append(params, map[string]interface{}{"name": k, "in": "query", "schema": map[string]string{"type": o.Query[k]}})
		}
		if params != nil {
			p["parameters"] = params
		}
		switch {
		case o.Request == "binary":
			p["requestBody"] = map[string]interface{}{"content": map[string]interface{}{"application/octet-stream": map[string]interface{}{"schema": map[string]string{"type": "string", "format": "binary"}}}}
		case o.Request == "text":
			p["requestBody"] = map[string]interface{}{"content": map[string]interface{}{"text/x-redx-box": map[string]interface{}{"schema": map[string]string{"type": "string"}}}}
		case o.Body != nil:
			props := map[string]interface{}{}
			for k, t := range o.Body {
				if t == "any" {
					props[k] = map[string]interface{}{}
				} else {
					props[k] = map[string]string{"type": t}
				}
			}
			p["requestBody"] = map[string]interface{}{"content": map[string]interface{}{"application/json": map[string]interface{}{"schema": map[string]interface{}{"type": "object", "properties": props}}}}
		}
		resp := map[string]interface{}{"description": "OK"}
		switch o.Response {
		case "json":
			resp["content"] = map[string]interface{}{"application/json": map[string]interface{}{"schema": map[string]string{"type": "object"}}}
		case "text":
			resp["content"] = map[string]interface{}{"text/x-redx-box": map[string]interface{}{"schema": map[string]string{"type": "string"}}}
		case "binary":
			resp["content"] = map[string]interface{}{"application/octet-stream": map[string]interface{}{"schema": map[string]string{"type": "string", "format": "binary"}}}
		case "websocket":
			p["x-redx-websocket"] = true
			resp = map[string]interface{}{"description": "WebSocket upgrade (101); one JSON event per message"}
		}
		code := "200"
		if o.Response == "websocket" {
			code = "101"
		}
		p["responses"] = map[string]interface{}{code: resp, "default": map[string]interface{}{"$ref": "#/components/responses/Error"}}
		if paths[o.Path] == nil {
			paths[o.Path] = map[string]interface{}{}
		}
		paths[o.Path][strings.ToLower(o.Method)] = p
	}
	dl := []interface{}{}
	for _, d := range s.Danger {
		dl = append(dl, map[string]interface{}{"name": d.Name, "level": d.Level, "meaning": d.Meaning})
	}
	doc := map[string]interface{}{
		"openapi": "3.1.0",
		"info": map[string]interface{}{"title": s.Name, "version": s.Version, "description": header + " Every operation carries x-redx-danger (" +
			"safe < write < admin < dangerous) and x-redx-auth. SDKs refuse dangerous operations unless the call is confirmed.",
			"x-redx-danger-levels": dl, "x-rottenapple-levels": s.RALevels},
		"servers":  []interface{}{map[string]string{"url": "http://127.0.0.1:7777"}},
		"security": []interface{}{map[string]interface{}{"bearer": []string{}}},
		"paths":    paths,
		"components": map[string]interface{}{
			"securitySchemes": map[string]interface{}{"bearer": map[string]string{"type": "http", "scheme": "bearer"}},
			"responses": map[string]interface{}{"Error": map[string]interface{}{"description": "Error", "content": map[string]interface{}{"application/json": map[string]interface{}{
				"schema": map[string]interface{}{"type": "object", "required": []string{"error", "code", "message"}, "properties": map[string]interface{}{
					"code":    map[string]string{"type": "string", "description": "Stable machine-readable error code (for example not_found, unauthorized, rate_limited, billing_off, bad_plan, plan_required). Safe to switch on."},
					"message": map[string]string{"type": "string", "description": "Human-readable explanation for display."},
					"error":   map[string]string{"type": "string", "description": "Legacy field kept for compatibility. On /v1/billing/* and account routes it equals code; elsewhere it carries the previous message text. New clients should read code and message."},
					"upgrade": map[string]string{"type": "string", "description": "Present on quota errors: where to change plan."},
				}}}}}},
		},
	}
	b, _ := json.MarshalIndent(doc, "", " ")
	return string(b) + "\n"
}

func keys(m map[string]string) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// ---------------------------------------------------------------- Go

func goOps(s *Spec) string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n\npackage redx\n\nimport \"context\"\n\n", header)
	b.WriteString("// Operations is the table of every RedX HTTP operation, keyed by id.\nvar Operations = map[string]Operation{\n")
	for _, o := range s.Operations {
		fmt.Fprintf(&b, "\t%s: {ID: %s, Group: %s, Method: %s, Path: %s, Shorthand: %s, Auth: %s, Danger: %s, Response: %s, Request: %s, HostConfirm: %s, Summary: %s},\n",
			quoteGo(o.ID), quoteGo(o.ID), quoteGo(o.Group), quoteGo(o.Method), quoteGo(o.Path), quoteGo(o.Shorthand), quoteGo(o.Auth), "Danger"+pascal(o.Danger), quoteGo(o.Response), quoteGo(requestKind(o)), quoteGo(o.HostConfirm), quoteGo(o.Summary))
	}
	b.WriteString("}\n\n// segmentParams are pack and media paths: each slash-separated segment is escaped, the slashes stay.\nvar segmentParams = map[string]bool{")
	for i, x := range s.ParamEncoding.Segments {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(&b, "%s: true", quoteGo(x))
	}
	b.WriteString("}\n")
	for _, o := range s.Operations {
		if o.Response == "websocket" || goHandwritten[o.ID] {
			continue
		}
		var sig, args []string
		for _, p := range o.pathParams() {
			sig = append(sig, p+" string")
			args = append(args, fmt.Sprintf("%s: %s", quoteGo(p), p))
		}
		fmt.Fprintf(&b, "\n// %s: %s\n//\n// %s %s, auth %s, danger %s.\n", pascal(o.ID), oneLine(o.Summary), o.Method, o.Path, o.Auth, o.Danger)
		fmt.Fprintf(&b, "func (c *Client) %s(ctx context.Context%s, a Args) (*Result, error) {\n", pascal(o.ID), prefixed(sig))
		if len(args) > 0 {
			fmt.Fprintf(&b, "\ta.Params = withParams(a.Params, map[string]string{%s})\n", strings.Join(args, ", "))
		}
		fmt.Fprintf(&b, "\treturn c.Call(ctx, %s, a)\n}\n", quoteGo(o.ID))
	}
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		panic(err)
	}
	return string(src)
}

// goHandwritten are operations whose Go method is written by hand with a typed signature (client.go); they
// stay reachable by id through Call.
var goHandwritten = map[string]bool{"bx": true}

func requestKind(o Op) string {
	if o.Request != "" {
		return o.Request
	}
	if o.Body != nil {
		return "json"
	}
	return ""
}

func prefixed(sig []string) string {
	if len(sig) == 0 {
		return ""
	}
	return ", " + strings.Join(sig, ", ")
}

// ---------------------------------------------------------------- JavaScript / TypeScript

func jsOps(s *Spec) string {
	var b strings.Builder
	fmt.Fprintf(&b, "'use strict';\n// %s\n\n", header)
	b.WriteString("const DANGER = Object.freeze({")
	for i, d := range s.Danger {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(&b, "%s: %d", d.Name, d.Level)
	}
	b.WriteString("});\n\nconst SEGMENT_PARAMS = new Set([")
	for i, x := range s.ParamEncoding.Segments {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(quoteJS(x))
	}
	b.WriteString("]);\n\nconst OPERATIONS = Object.freeze({\n")
	for _, o := range s.Operations {
		fmt.Fprintf(&b, "  %s: Object.freeze({ id: %s, group: %s, method: %s, path: %s, shorthand: %s, auth: %s, danger: %s, dangerLevel: %d, response: %s, request: %s, hostConfirm: %s, summary: %s }),\n",
			o.ID, quoteJS(o.ID), quoteJS(o.Group), quoteJS(o.Method), quoteJS(o.Path), quoteJS(o.Shorthand), quoteJS(o.Auth), quoteJS(o.Danger), level(s, o.Danger), quoteJS(o.Response), quoteJS(requestKind(o)), quoteJS(o.HostConfirm), quoteJS(o.Summary))
	}
	b.WriteString("});\n\n// install adds one method per operation to the client class: client.<id>({ db, <path params>, query, body, confirm }).\nfunction install(proto) {\n")
	for _, o := range s.Operations {
		if o.Response == "websocket" {
			continue
		}
		fmt.Fprintf(&b, "  if (!proto.%s) proto.%s = function (opts = {}) { return this.call(%s, opts); };\n", o.ID, o.ID, quoteJS(o.ID))
	}
	b.WriteString("}\n\nmodule.exports = { OPERATIONS, DANGER, SEGMENT_PARAMS, install };\n")
	return b.String()
}

func tsType(t string) string {
	switch t {
	case "string":
		return "string"
	case "integer", "number":
		return "number"
	case "boolean":
		return "boolean"
	case "array":
		return "unknown[]"
	case "object":
		return "Record<string, unknown>"
	}
	return "unknown"
}

func tsOps(s *Spec) string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n\n", header)
	b.WriteString("export type DangerName = ")
	for i, d := range s.Danger {
		if i > 0 {
			b.WriteString(" | ")
		}
		b.WriteString(quoteJS(d.Name))
	}
	b.WriteString(";\n\nexport interface Operation {\n  id: string; group: string; method: string; path: string; shorthand: string; auth: string;\n  danger: DangerName; dangerLevel: number; response: 'json' | 'text' | 'binary' | 'websocket'; request: string; hostConfirm: string; summary: string;\n}\n\n")
	b.WriteString("export interface CallOptions {\n  /** database; defaults to the client's */\n  db?: string;\n  query?: Record<string, string | number | boolean | undefined>;\n  body?: unknown;\n  headers?: Record<string, string>;\n  /** required for operations whose danger is \"dangerous\" */\n  confirm?: boolean;\n  [pathParam: string]: unknown;\n}\n\n")
	b.WriteString("export interface RedXOperations {\n")
	for _, o := range s.Operations {
		if o.Response == "websocket" {
			continue
		}
		var fields []string
		for _, p := range o.pathParams() {
			fields = append(fields, p+": string")
		}
		if o.hasDB() {
			fields = append(fields, "db?: string")
		}
		if o.Body != nil && o.Request == "" {
			var bf []string
			for _, k := range keys(o.Body) {
				bf = append(bf, fmt.Sprintf("%s?: %s", k, tsType(o.Body[k])))
			}
			fields = append(fields, "body?: { "+strings.Join(bf, "; ")+" }")
		} else if o.Request != "" {
			fields = append(fields, "body: string | Uint8Array | Buffer")
		}
		if o.Query != nil {
			var qf []string
			for _, k := range keys(o.Query) {
				qf = append(qf, fmt.Sprintf("%s?: %s", k, tsType(o.Query[k])))
			}
			fields = append(fields, "query?: { "+strings.Join(qf, "; ")+" }")
		}
		if o.Danger == "dangerous" {
			fields = append(fields, "confirm: true")
		}
		fields = append(fields, "headers?: Record<string, string>")
		ret := "Promise<any>"
		switch o.Response {
		case "text":
			ret = "Promise<string>"
		case "binary":
			ret = "Promise<Buffer>"
		}
		opt := "?"
		if len(o.pathParams()) > 0 || o.Danger == "dangerous" || o.Request != "" {
			opt = ""
		}
		fmt.Fprintf(&b, "  /** %s (%s %s; auth %s; danger %s) */\n  %s(opts%s: { %s }): %s;\n", jsComment(o.Summary), o.Method, jsComment(o.Path), o.Auth, o.Danger, o.ID, opt, strings.Join(fields, "; "), ret)
	}
	b.WriteString("}\n\nexport declare const OPERATIONS: Readonly<Record<string, Operation>>;\nexport declare const DANGER: Readonly<Record<DangerName, number>>;\n")
	return b.String()
}

// ---------------------------------------------------------------- Python

func pyOps(s *Spec) string {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\"\"\"The RedX operation table and one method per operation (mixed into redx.RedX).\"\"\"\n\nfrom typing import Any, Dict, Optional\n\n", header)
	b.WriteString("DANGER = {")
	for i, d := range s.Danger {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(&b, "%s: %d", quotePy(d.Name), d.Level)
	}
	b.WriteString("}\n\nSEGMENT_PARAMS = frozenset({")
	for i, x := range s.ParamEncoding.Segments {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(quotePy(x))
	}
	b.WriteString("})\n\nOPERATIONS: Dict[str, Dict[str, Any]] = {\n")
	for _, o := range s.Operations {
		fmt.Fprintf(&b, "    %s: {\"id\": %s, \"group\": %s, \"method\": %s, \"path\": %s, \"shorthand\": %s, \"auth\": %s, \"danger\": %s, \"danger_level\": %d, \"response\": %s, \"request\": %s, \"host_confirm\": %s, \"summary\": %s},\n",
			quotePy(o.ID), quotePy(o.ID), quotePy(o.Group), quotePy(o.Method), quotePy(o.Path), quotePy(o.Shorthand), quotePy(o.Auth), quotePy(o.Danger), level(s, o.Danger), quotePy(o.Response), quotePy(requestKind(o)), quotePy(o.HostConfirm), quotePy(o.Summary))
	}
	b.WriteString("}\n\n\nclass Operations:\n    \"\"\"One method per operation. Each returns parsed JSON (bytes for binary, str for Box text).\"\"\"\n\n    def call(self, op_id: str, **kw: Any) -> Any:  # implemented by RedX\n        raise NotImplementedError\n")
	for _, o := range s.Operations {
		if o.Response == "websocket" {
			continue
		}
		var sig, pass []string
		for _, p := range o.pathParams() {
			sig = append(sig, p+": str")
			pass = append(pass, p+"="+p)
		}
		sig = append(sig, "*")
		if o.hasDB() {
			sig = append(sig, "db: Optional[str] = None")
			pass = append(pass, "db=db")
		}
		if o.hasBody() {
			sig = append(sig, "body: Any = None")
			pass = append(pass, "body=body")
		}
		if o.Query != nil {
			sig = append(sig, "query: Optional[Dict[str, Any]] = None")
			pass = append(pass, "query=query")
		}
		sig = append(sig, "confirm: bool = False", "headers: Optional[Dict[str, str]] = None")
		pass = append(pass, "confirm=confirm", "headers=headers")
		doc := pyDoc(fmt.Sprintf("%s (%s %s; auth %s; danger %s)", o.Summary, o.Method, o.Path, o.Auth, o.Danger))
		fmt.Fprintf(&b, "\n    def %s(self, %s) -> Any:\n        \"\"\"%s\"\"\"\n        return self.call(%s, %s)\n",
			snake(o.ID), strings.Join(sig, ", "), doc, quotePy(o.ID), strings.Join(pass, ", "))
	}
	return b.String()
}

// ---------------------------------------------------------------- Swift

func swiftOps(s *Spec) string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n\nimport Foundation\n\n", header)
	b.WriteString("public enum DangerLevel: Int, Sendable, Comparable {\n")
	for _, d := range s.Danger {
		fmt.Fprintf(&b, "    /// %s\n    case %s = %d\n", oneLine(d.Meaning), d.Name, d.Level)
	}
	b.WriteString("    public static func < (a: DangerLevel, b: DangerLevel) -> Bool { a.rawValue < b.rawValue }\n}\n\n")
	b.WriteString("public struct Operation: Sendable {\n    public let id, group, method, path, shorthand, auth, response, request, hostConfirm, summary: String\n    public let danger: DangerLevel\n}\n\n")
	b.WriteString("let segmentParams: Set<String> = [")
	for i, x := range s.ParamEncoding.Segments {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(quoteSwift(x))
	}
	b.WriteString("]\n\npublic let operations: [String: Operation] = [\n")
	for _, o := range s.Operations {
		fmt.Fprintf(&b, "    %s: Operation(id: %s, group: %s, method: %s, path: %s, shorthand: %s, auth: %s, response: %s, request: %s, hostConfirm: %s, summary: %s, danger: .%s),\n",
			quoteSwift(o.ID), quoteSwift(o.ID), quoteSwift(o.Group), quoteSwift(o.Method), quoteSwift(o.Path), quoteSwift(o.Shorthand), quoteSwift(o.Auth), quoteSwift(o.Response), quoteSwift(requestKind(o)), quoteSwift(o.HostConfirm), quoteSwift(o.Summary), o.Danger)
	}
	b.WriteString("]\n\nextension RedXClient {\n")
	for _, o := range s.Operations {
		if o.Response == "websocket" {
			continue
		}
		var sig, params []string
		for _, p := range o.pathParams() {
			sig = append(sig, p+": String")
			params = append(params, fmt.Sprintf("%s: %s", quoteSwift(p), p))
		}
		if o.hasDB() {
			sig = append(sig, "db: String? = nil")
		}
		if o.Request != "" {
			sig = append(sig, "body: Data")
		} else if o.Body != nil {
			sig = append(sig, "body: [String: Any]? = nil")
		}
		if o.Query != nil {
			sig = append(sig, "query: [String: Any]? = nil")
		}
		if o.Danger == "dangerous" {
			sig = append(sig, "confirm: Bool = false")
		}
		call := []string{quoteSwift(o.ID)}
		pm := "[:]"
		if len(params) > 0 {
			pm = "[" + strings.Join(params, ", ") + "]"
		}
		call = append(call, "params: "+pm)
		if o.hasDB() {
			call = append(call, "db: db")
		}
		if o.Request != "" {
			call = append(call, "rawBody: body")
		} else if o.Body != nil {
			call = append(call, "body: body")
		}
		if o.Query != nil {
			call = append(call, "query: query")
		}
		if o.Danger == "dangerous" {
			call = append(call, "confirm: confirm")
		}
		fmt.Fprintf(&b, "    /// %s (%s %s; auth %s; danger %s)\n    @discardableResult\n    public func %s(%s) async throws -> RedXResult {\n        try await call(%s)\n    }\n\n",
			oneLine(o.Summary), o.Method, o.Path, o.Auth, o.Danger, o.ID, strings.Join(sig, ", "), strings.Join(call, ", "))
	}
	b.WriteString("}\n")
	return b.String()
}

// ---------------------------------------------------------------- C#

func csOps(s *Spec) string {
	var b strings.Builder
	fmt.Fprintf(&b, "// <auto-generated>\n// %s\n// </auto-generated>\n#nullable enable\nusing System.Collections.Generic;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nnamespace RedX\n{\n", header)
	b.WriteString("    /// <summary>How risky an operation is. SDKs refuse Dangerous unless the call is confirmed.</summary>\n    public enum DangerLevel\n    {\n")
	for _, d := range s.Danger {
		fmt.Fprintf(&b, "        /// <summary>%s</summary>\n        %s = %d,\n", csDoc(d.Meaning), pascal(d.Name), d.Level)
	}
	b.WriteString("    }\n\n    public sealed class Operation\n    {\n        public string Id = \"\", Group = \"\", Method = \"\", Path = \"\", Shorthand = \"\", Auth = \"\", Response = \"\", Request = \"\", HostConfirm = \"\", Summary = \"\";\n        public DangerLevel Danger;\n    }\n\n")
	b.WriteString("    public static class Operations\n    {\n        internal static readonly HashSet<string> SegmentParams = new HashSet<string> {")
	for i, x := range s.ParamEncoding.Segments {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(quoteCS(x))
	}
	b.WriteString(" };\n\n        public static readonly IReadOnlyDictionary<string, Operation> All = new Dictionary<string, Operation>\n        {\n")
	for _, o := range s.Operations {
		fmt.Fprintf(&b, "            [%s] = new Operation { Id = %s, Group = %s, Method = %s, Path = %s, Shorthand = %s, Auth = %s, Response = %s, Request = %s, HostConfirm = %s, Summary = %s, Danger = DangerLevel.%s },\n",
			quoteCS(o.ID), quoteCS(o.ID), quoteCS(o.Group), quoteCS(o.Method), quoteCS(o.Path), quoteCS(o.Shorthand), quoteCS(o.Auth), quoteCS(o.Response), quoteCS(requestKind(o)), quoteCS(o.HostConfirm), quoteCS(o.Summary), pascal(o.Danger))
	}
	b.WriteString("        };\n    }\n\n    public partial class RedXClient\n    {\n")
	for _, o := range s.Operations {
		if o.Response == "websocket" || goHandwritten[o.ID] { // Bx has a typed hand-written method in every SDK
			continue
		}
		var sig, params []string
		for _, p := range o.pathParams() {
			sig = append(sig, "string "+p)
			params = append(params, fmt.Sprintf("[%s] = %s", quoteCS(p), p))
		}
		if o.Request != "" {
			sig = append(sig, "byte[] body")
		}
		if o.hasDB() {
			sig = append(sig, "string? db = null")
		}
		if o.Body != nil && o.Request == "" {
			sig = append(sig, "object? body = null")
		}
		if o.Query != nil {
			sig = append(sig, "IDictionary<string, object?>? query = null")
		}
		if o.Danger == "dangerous" {
			sig = append(sig, "bool confirm = false")
		}
		sig = append(sig, "CancellationToken ct = default")
		pm := "null"
		if len(params) > 0 {
			pm = "new Dictionary<string, string> { " + strings.Join(params, ", ") + " }"
		}
		args := []string{quoteCS(o.ID), pm}
		args = append(args, ternary(o.hasDB(), "db", "null"))
		args = append(args, ternary(o.Body != nil && o.Request == "", "body", "null"))
		args = append(args, ternary(o.Request != "", "body", "null"))
		args = append(args, ternary(o.Query != nil, "query", "null"))
		args = append(args, ternary(o.Danger == "dangerous", "confirm", "false"), "ct")
		fmt.Fprintf(&b, "        /// <summary>%s (%s %s; auth %s; danger %s)</summary>\n        public Task<RedXResult> %sAsync(%s) =>\n            CallAsync(%s);\n\n",
			csDoc(o.Summary), o.Method, csDoc(o.Path), o.Auth, o.Danger, pascal(o.ID), strings.Join(sig, ", "), strings.Join(args, ", "))
	}
	b.WriteString("    }\n}\n")
	return b.String()
}

func ternary(c bool, a, b string) string {
	if c {
		return a
	}
	return b
}

func escXML(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;").Replace(s)
}

// ---------------------------------------------------------------- C

func cOps(s *Spec) string {
	var b strings.Builder
	fmt.Fprintf(&b, "/* %s */\n#ifndef REDX_OPS_H\n#define REDX_OPS_H\n\n/* Danger levels of operations (redx_danger_level). Dangerous calls need \"confirm\": true in the args. */\n", header)
	for _, d := range s.Danger {
		fmt.Fprintf(&b, "#define REDX_DANGER_%s %d /* %s */\n", strings.ToUpper(d.Name), d.Level, cComment(d.Meaning))
	}
	b.WriteString("\n/* Operation ids accepted by redx_call (see api/redx-api.json). */\n")
	for _, o := range s.Operations {
		if o.Response == "websocket" {
			continue
		}
		fmt.Fprintf(&b, "#define REDX_OP_%s %s /* %s %s, %s */\n", strings.ToUpper(snake(o.ID)), quoteC(o.ID), o.Method, cComment(strings.ReplaceAll(o.Path, "*", "")), o.Danger)
	}
	b.WriteString("\n#endif\n")
	return b.String()
}
